class DAGTask:
    def __init__(self, i, T, D, G):
        self.i = i
        self.T = T
        self.D = D
        self.G = G  # (V, E)
        for v in G.V:
            v.C = execution_time(v)

task_set = [DAGTask(i, T_i, D_i, G_i) for i in range(n)]

def assign_local_offsets_deadlines(G, D_i):
    for v in topological_sort(G.V):
        if v.is_source():
            o_v = 0
            d_v = D_i
        else:
            preds = predecessors(v)
            o_v = max(pred.d + pred.C for pred in preds)
            d_v = min(D_i, min(pred.d + pred.C for pred in preds))
        v.o = o_v
        v.d = d_v
    return G

def is_schedulable(task_set, m):
    for t in range(1, max_D + 1):
        total_work = sum(dbf_j(task_j, t) for task_j in task_set)
        if total_work > m * t:
            return False
    return True

def dbf_j(tau_j, t):
    # Using local offsets
    num_jobs = floor(t / tau_j.T) + 1
    return num_jobs * sum(min(C_v, max(0, t - v.o)) for v in tau_j.G.V)
